using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace JueMingR.TerrariaHost.Combat.Prediction
{
    // These are the same metadata/camera substitutions used by the original
    // Harmony boundary. Prepare them once, before load, so a large NPC.AI body
    // need not be regenerated by Harmony on every worker start. BCL delegate
    // fields keep the private image independent of product assembly references.
    internal static class NativePresentationImage
    {
        internal const string GuardName="JueMingR.PrivatePrediction.PresentationGuard";
        private const string Asset="ReLogic.Content.Asset`1<Microsoft.Xna.Framework.Graphics.Texture2D>";
        internal static void Rewrite(NativeTileImage.MetadataApi api,object module)
        {
            object system=api.Get(module,"TypeSystem"),obj=api.Get(system,"Object");
            object guard=api.New("TypeDefinition","JueMingR.PrivatePrediction","PresentationGuard",api.Enum("TypeAttributes",0x180),obj);
            api.Call(api.Get(module,"Types"),"Add",guard);
            object metadata=Field(api,module,guard,"Metadata",typeof(Func<object,int,int>));
            object rectangle=Field(api,module,guard,"Rectangle",typeof(Func<object,object,object>));
            object camera=Field(api,module,guard,"Camera",typeof(Func<object>));
            var bridges=new Dictionary<string,object>();int metadataMethods=0,cameraMethods=0,replaced=0;
            foreach(string typeName in new[]{"Terraria.NPC","Terraria.Gore","Terraria.GameContent.Events.DD2Event"})
            foreach(object method in (IEnumerable)api.Get(api.Call(module,"GetType",typeName),"Methods"))
            {
                if(!(bool)api.Get(method,"HasBody"))continue;
                var code=((IEnumerable)api.Get(api.Get(method,"Body"),"Instructions")).Cast<object>().ToArray();
                var kinds=new int[code.Length];bool hasMetadata=false,hasFilter=false,hasInstance=false,hasCameraField=false;object assetGetter=null;
                // Classify the fixed original instructions once. Re-scanning
                // giant AI bodies and enumerating unrelated method parameters
                // repeatedly cannot add evidence to these six substitutions.
                for(int i=0;i<code.Length;i++)
                {
                    object operand=api.Get(code[i],"Operand");int kind=kinds[i]=Kind(api,operand);
                    hasMetadata|=kind>=0 && kind<=3;hasFilter|=kind==5;if(kind==4 && assetGetter==null)assetGetter=operand;
                    hasInstance|=IsField(api,code[i],"instance","Ldsfld");hasCameraField|=IsField(api,code[i],"CameraModifiers","Ldfld");
                }
                bool hasCamera=hasInstance && hasCameraField;
                if(hasMetadata)metadataMethods++;if(hasFilter || hasCamera)cameraMethods++;
                for(int i=0;i<code.Length;i++)
                {
                    object operand=api.Get(code[i],"Operand");int kind=kinds[i];
                    if(hasMetadata && kind==4)
                    {
                        if(i+1>=code.Length || kinds[i+1]!=3)throw new InvalidDataException("Unclosed private asset Value.");
                        api.Set(code[i],"OpCode",api.Opcode("Nop"));api.Set(code[i],"Operand",null);continue;
                    }
                    if(hasMetadata && kind>=0 && kind<=3 || kind==5)
                    {
                        string key=kind.ToString();object bridge;
                        if(!bridges.TryGetValue(key,out bridge))
                        {bridge=kind==3?Rectangle(api,module,guard,rectangle,operand,assetGetter):kind==5?Filter(api,guard,operand):Metadata(api,module,guard,metadata,operand,kind);bridges.Add(key,bridge);}
                        api.Set(code[i],"OpCode",api.Opcode("Call"));api.Set(code[i],"Operand",bridge);replaced++;
                    }
                    if(hasCamera && i+1<code.Length && IsField(api,code[i],"instance","Ldsfld") && IsField(api,code[i+1],"CameraModifiers","Ldfld"))
                    {
                        object bridge;if(!bridges.TryGetValue("camera",out bridge)){bridge=Camera(api,module,guard,camera,api.Get(code[i],"Operand"),api.Get(code[i+1],"Operand"));bridges.Add("camera",bridge);}
                        api.Set(code[i],"OpCode",api.Opcode("Nop"));api.Set(code[i],"Operand",null);api.Set(code[i+1],"OpCode",api.Opcode("Call"));api.Set(code[i+1],"Operand",bridge);replaced++;i++;
                    }
                }
            }
            if(metadataMethods!=9 || cameraMethods!=5 || bridges.Count!=6)throw new InvalidDataException("Presentation method inventory changed: metadata="+metadataMethods+" camera="+cameraMethods+" bridges="+bridges.Count);
            Console.Error.WriteLine("PRESENTATION private metadata-methods="+metadataMethods+" camera-methods="+cameraMethods+" replacement-calls="+replaced);
        }
        internal static void VerifyWritten(NativeTileImage.MetadataApi api,object module)
        {
            object guard=api.Call(module,"GetType",GuardName);if(guard==null || ((IEnumerable)api.Get(guard,"Methods")).Cast<object>().Count()!=6)throw new InvalidDataException("Private presentation bridge shape.");
            int calls=0;
            foreach(string typeName in new[]{"Terraria.NPC","Terraria.Gore","Terraria.GameContent.Events.DD2Event"})
            foreach(object method in (IEnumerable)api.Get(api.Call(module,"GetType",typeName),"Methods"))
            {
                if(!(bool)api.Get(method,"HasBody"))continue;
                foreach(object instruction in (IEnumerable)api.Get(api.Get(method,"Body"),"Instructions"))
                {
                    object operand=api.Get(instruction,"Operand");int kind=Kind(api,operand);
                    if(kind>=0 && kind<=3 || kind==5 || IsField(api,instruction,"CameraModifiers","Ldfld"))throw new InvalidDataException("Unprepared presentation call after write.");
                    if(operand!=null && api.Type("MethodReference").IsInstanceOfType(operand) && (string)api.Get(api.Get(operand,"DeclaringType"),"FullName")==GuardName)calls++;
                }
            }
            if(calls<20)throw new InvalidDataException("Incomplete presentation bridges.");
        }
        private static int Kind(NativeTileImage.MetadataApi api,object value)
        {
            if(value==null || !api.Type("MethodReference").IsInstanceOfType(value))return -1;
            string owner=(string)api.Get(api.Get(value,"DeclaringType"),"FullName"),name=(string)api.Get(value,"Name");
            if(owner!=Asset && owner!="Terraria.Utils" && owner!="Terraria.DataStructures.SpriteFrame" && owner!="Terraria.Graphics.Effects.EffectManager`1<Terraria.Graphics.Effects.Filter>")return -1;
            var args=((IEnumerable)api.Get(value,"Parameters")).Cast<object>().Select(p=>(string)api.Get(api.Get(p,"ParameterType"),"FullName")).ToArray();
            if(owner==Asset && args.Length==0){if(name=="get_IsLoaded")return 0;if(name=="get_Value")return 4;}
            if(owner=="Terraria.Utils" && args.SequenceEqual(new[]{Asset})){if(name=="Width")return 1;if(name=="Height")return 2;}
            if(owner=="Terraria.DataStructures.SpriteFrame" && name=="GetSourceRectangle" && args.SequenceEqual(new[]{"Microsoft.Xna.Framework.Graphics.Texture2D"}))return 3;
            if(owner=="Terraria.Graphics.Effects.EffectManager`1<Terraria.Graphics.Effects.Filter>" && name=="Deactivate" && args.SequenceEqual(new[]{"System.String","System.Object[]"}))return 5;
            return -1;
        }
        private static bool IsField(NativeTileImage.MetadataApi api,object instruction,string name,string opcode)
        {object value=api.Get(instruction,"Operand");return api.Code(instruction)==opcode && value!=null && api.Type("FieldReference").IsInstanceOfType(value) && (string)api.Get(value,"Name")==name && (string)api.Get(api.Get(value,"DeclaringType"),"FullName")=="Terraria.Main";}
        private static object Field(NativeTileImage.MetadataApi api,object module,object guard,string name,Type type)
        {object field=api.New("FieldDefinition",name,api.Enum("FieldAttributes",0x16),api.Call(module,"ImportReference",type));api.Call(api.Get(guard,"Fields"),"Add",field);return field;}
        private static object Method(NativeTileImage.MetadataApi api,object guard,string name,object result,params object[] parameters)
        {object method=api.New("MethodDefinition",name,api.Enum("MethodAttributes",0x96),result);foreach(object parameter in parameters)api.Call(api.Get(method,"Parameters"),"Add",api.New("ParameterDefinition",parameter));api.Call(api.Get(guard,"Methods"),"Add",method);return method;}
        private static void Add(NativeTileImage.MetadataApi api,object code,string opcode,params object[] operands){api.Call(code,"Add",api.Instruction(opcode,operands));}
        private static object Metadata(NativeTileImage.MetadataApi api,object module,object guard,object handler,object original,int kind)
        {
            object parameter=kind==0?api.Get(original,"DeclaringType"):api.Get(((IEnumerable)api.Get(original,"Parameters")).Cast<object>().First(),"ParameterType");
            object method=Method(api,guard,"Metadata"+kind,api.Get(original,"ReturnType"),parameter),code=api.Get(api.Get(method,"Body"),"Instructions"),fallback=api.Instruction("Ldarg_0");
            Add(api,code,"Ldsfld",handler);Add(api,code,"Brfalse",fallback);Add(api,code,"Ldsfld",handler);Add(api,code,"Ldarg_0");Add(api,code,"Ldc_I4",kind);Add(api,code,"Callvirt",api.Call(module,"ImportReference",typeof(Func<object,int,int>).GetMethod("Invoke")));Add(api,code,"Ret");
            api.Call(code,"Add",fallback);Add(api,code,kind==0?"Callvirt":"Call",original);Add(api,code,"Ret");return method;
        }
        private static object Rectangle(NativeTileImage.MetadataApi api,object module,object guard,object handler,object original,object getter)
        {
            // SourceRectangle only reads SpriteFrame. Boxing a value copy for
            // the BCL bridge preserves that contract; there is no write-back.
            if(getter==null)throw new InvalidDataException("Missing original asset getter for source rectangle.");
            object frame=api.Get(original,"DeclaringType"),asset=api.Get(getter,"DeclaringType"),result=api.Get(original,"ReturnType");
            object method=Method(api,guard,"Rectangle",result,api.New("ByReferenceType",frame),asset),code=api.Get(api.Get(method,"Body"),"Instructions"),fallback=api.Instruction("Ldarg_0");
            Add(api,code,"Ldsfld",handler);Add(api,code,"Brfalse",fallback);Add(api,code,"Ldsfld",handler);Add(api,code,"Ldarg_0");Add(api,code,"Ldobj",frame);Add(api,code,"Box",frame);Add(api,code,"Ldarg_1");Add(api,code,"Callvirt",api.Call(module,"ImportReference",typeof(Func<object,object,object>).GetMethod("Invoke")));Add(api,code,"Unbox_Any",result);Add(api,code,"Ret");
            api.Call(code,"Add",fallback);Add(api,code,"Ldarg_1");Add(api,code,"Callvirt",getter);Add(api,code,"Call",original);Add(api,code,"Ret");return method;
        }
        private static object Filter(NativeTileImage.MetadataApi api,object guard,object original)
        {
            if((string)api.Get(api.Get(original,"ReturnType"),"FullName")!="System.Void")throw new InvalidDataException("Filter return contract changed.");
            var args=new[]{api.Get(original,"DeclaringType")}.Concat(((IEnumerable)api.Get(original,"Parameters")).Cast<object>().Select(p=>api.Get(p,"ParameterType"))).ToArray();
            object method=Method(api,guard,"NoFilter",api.Get(original,"ReturnType"),args);Add(api,api.Get(api.Get(method,"Body"),"Instructions"),"Ret");return method;
        }
        private static object Camera(NativeTileImage.MetadataApi api,object module,object guard,object handler,object instance,object field)
        {
            object result=api.Get(field,"FieldType"),method=Method(api,guard,"Camera",result),code=api.Get(api.Get(method,"Body"),"Instructions"),fallback=api.Instruction("Ldsfld",instance);
            Add(api,code,"Ldsfld",handler);Add(api,code,"Brfalse",fallback);Add(api,code,"Ldsfld",handler);Add(api,code,"Callvirt",api.Call(module,"ImportReference",typeof(Func<object>).GetMethod("Invoke")));Add(api,code,"Castclass",result);Add(api,code,"Ret");
            api.Call(code,"Add",fallback);Add(api,code,"Ldfld",field);Add(api,code,"Ret");return method;
        }
    }
}
